using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace TokenAuth
{
    public sealed class TokenEntry
    {
        public string TokenHash { get; set; }
        public string UserId { get; set; }
        public DateTime ExpiresAt { get; set; }
        public int RemainingUses { get; set; }
        public bool IsRevoked { get; set; }
        public string[] Permissions { get; set; }
    }

    public sealed class AuthResult
    {
        public bool IsAuthenticated { get; set; }
        public string UserId { get; set; }
        public string[] Permissions { get; set; }
        public string Error { get; set; }
    }

    public sealed class SecureTokenService
    {
        private readonly Dictionary<string, TokenEntry> _tokenStore = new();
        private readonly object _storeLock = new object();
        private readonly byte[] _hmacKey;
        private readonly int _maxTokensPerUser;
        private readonly TimeSpan _defaultExpiry;
        private readonly ConcurrentDictionary<string, int> _failedAttempts = new();
        private const int MaxFailedAttempts = 5;
        private const int LockoutMinutes = 15;
        private readonly ConcurrentDictionary<string, DateTime> _lockouts = new();

        public SecureTokenService(byte[] hmacKey, int maxTokensPerUser = 10, TimeSpan? defaultExpiry = null)
        {
            if (hmacKey == null || hmacKey.Length < 32)
                throw new ArgumentException("HMAC key must be at least 32 bytes");
            _hmacKey = (byte[])hmacKey.Clone();
            _maxTokensPerUser = maxTokensPerUser;
            _defaultExpiry = defaultExpiry ?? TimeSpan.FromHours(1);
        }

        public string IssueToken(string userId, string[] permissions, int maxUses = -1, TimeSpan? customExpiry = null)
        {
            if (string.IsNullOrWhiteSpace(userId))
                throw new ArgumentException("userId required");
            if (permissions == null || permissions.Length == 0)
                throw new ArgumentException("permissions required");

            var rawToken = GenerateSecureToken();
            var tokenHash = ComputeTokenHash(rawToken);
            var entry = new TokenEntry
            {
                TokenHash = tokenHash,
                UserId = userId,
                ExpiresAt = DateTime.UtcNow.Add(customExpiry ?? _defaultExpiry),
                RemainingUses = maxUses,
                IsRevoked = false,
                Permissions = (string[])permissions.Clone()
            };

            lock (_storeLock)
            {
                int userTokenCount = 0;
                foreach (var kvp in _tokenStore)
                {
                    if (kvp.Value.UserId == userId && !kvp.Value.IsRevoked)
                        userTokenCount++;
                }
                if (userTokenCount >= _maxTokensPerUser)
                    throw new InvalidOperationException("Token limit reached for user");
                _tokenStore[tokenHash] = entry;
            }

            return rawToken;
        }

        public AuthResult ValidateAndConsume(string rawToken, string requiredPermission, string clientIp)
        {
            if (string.IsNullOrEmpty(rawToken) || string.IsNullOrEmpty(requiredPermission))
                return new AuthResult { IsAuthenticated = false, Error = "Invalid input" };

            if (IsLockedOut(clientIp))
                return new AuthResult { IsAuthenticated = false, Error = "Account locked" };

            var tokenHash = ComputeTokenHash(rawToken);
            TokenEntry entry;
            bool isValid;

            // Phase 1: Validate token state
            lock (_storeLock)
            {
                if (!_tokenStore.TryGetValue(tokenHash, out entry))
                {
                    RecordFailedAttempt(clientIp);
                    return new AuthResult { IsAuthenticated = false, Error = "Token not found" };
                }

                isValid = !entry.IsRevoked &&
                          entry.ExpiresAt > DateTime.UtcNow &&
                          HasPermission(entry.Permissions, requiredPermission);
            }

            if (!isValid)
            {
                RecordFailedAttempt(clientIp);
                return new AuthResult { IsAuthenticated = false, Error = "Token invalid or expired" };
            }

            // Phase 2: Consume a use (decrement counter)
            lock (_storeLock)
            {
                // Re-fetch in case of concurrent modification
                if (!_tokenStore.TryGetValue(tokenHash, out entry))
                    return new AuthResult { IsAuthenticated = false, Error = "Token not found" };

                if (entry.IsRevoked)
                    return new AuthResult { IsAuthenticated = false, Error = "Token revoked" };

                if (entry.RemainingUses == 0)
                    return new AuthResult { IsAuthenticated = false, Error = "Token exhausted" };

                if (entry.RemainingUses > 0)
                    entry.RemainingUses--;
            }

            ClearFailedAttempts(clientIp);
            return new AuthResult
            {
                IsAuthenticated = true,
                UserId = entry.UserId,
                Permissions = entry.Permissions
            };
        }

        public void RevokeToken(string rawToken)
        {
            var tokenHash = ComputeTokenHash(rawToken);
            lock (_storeLock)
            {
                if (_tokenStore.TryGetValue(tokenHash, out var entry))
                    entry.IsRevoked = true;
            }
        }

        public void RevokeAllUserTokens(string userId)
        {
            lock (_storeLock)
            {
                foreach (var kvp in _tokenStore)
                {
                    if (kvp.Value.UserId == userId)
                        kvp.Value.IsRevoked = true;
                }
            }
        }

        private bool HasPermission(string[] granted, string required)
        {
            for (int i = 0; i < granted.Length; i++)
            {
                if (ConstantTimeEquals(
                    Encoding.UTF8.GetBytes(granted[i]),
                    Encoding.UTF8.GetBytes(required)))
                    return true;
            }
            return false;
        }

        private static bool ConstantTimeEquals(byte[] a, byte[] b)
        {
            if (a.Length != b.Length)
                return false;
            int diff = 0;
            for (int i = 0; i < a.Length; i++)
                diff |= a[i] ^ b[i];
            return diff == 0;
        }

        private string ComputeTokenHash(string rawToken)
        {
            using var hmac = new HMACSHA256(_hmacKey);
            var hash = hmac.ComputeHash(Encoding.UTF8.GetBytes(rawToken));
            return Convert.ToBase64String(hash);
        }

        private static string GenerateSecureToken()
        {
            var bytes = new byte[32];
            using var rng = RandomNumberGenerator.Create();
            rng.GetBytes(bytes);
            return Convert.ToBase64String(bytes);
        }

        private bool IsLockedOut(string clientIp)
        {
            if (_lockouts.TryGetValue(clientIp, out var lockoutUntil))
            {
                if (DateTime.UtcNow < lockoutUntil)
                    return true;
                _lockouts.TryRemove(clientIp, out _);
            }
            return false;
        }

        private void RecordFailedAttempt(string clientIp)
        {
            var attempts = _failedAttempts.AddOrUpdate(clientIp, 1, (_, c) => c + 1);
            if (attempts >= MaxFailedAttempts)
            {
                _lockouts[clientIp] = DateTime.UtcNow.AddMinutes(LockoutMinutes);
                _failedAttempts.TryRemove(clientIp, out _);
            }
        }

        private void ClearFailedAttempts(string clientIp)
        {
            _failedAttempts.TryRemove(clientIp, out _);
        }
    }
}
